# Build a Test Summary Report (TSR) from golden dataset V1 vs V2 comparison
# Includes prompt text and PR context so the report is self-contained for review
import json as _json
import subprocess
from datetime import datetime, timezone

# Fall back to in-memory DataFrames if LangSmith query returned empty
src_v1 = df_ls_v1 if len(df_ls_v1) > 0 else df_golden_v1.reset_index()
src_v2 = df_ls_v2 if len(df_ls_v2) > 0 else df_golden_v2.reset_index()
source_label = "langsmith" if len(df_ls_v1) > 0 else "in_memory"

metric_cols = [c for c in src_v1.columns if c not in ("label", "prompt_version")]

# --- Git context for PR traceability ---
def _git(cmd):
    try:
        return subprocess.check_output(cmd, text=True, stderr=subprocess.DEVNULL).strip()
    except Exception:
        return None

git_sha = _git(["git", "rev-parse", "HEAD"])
git_branch = _git(["git", "rev-parse", "--abbrev-ref", "HEAD"])
git_short_sha = _git(["git", "rev-parse", "--short", "HEAD"])

# --- Identify failure modes in V1 and whether V2 fixed them ---
failure_modes = []
regressions = []

for _, row_v1 in src_v1.iterrows():
    label = row_v1["label"]
    row_v2 = src_v2[src_v2["label"] == label]
    if row_v2.empty:
        continue
    row_v2 = row_v2.iloc[0]

    for metric in metric_cols:
        v1_result = row_v1[metric]
        v2_result = row_v2[metric]

        if v1_result == "FAIL":
            failure_modes.append({
                "example": label,
                "metric": metric,
                "v1_result": "FAIL",
                "v2_result": v2_result,
                "fixed": v2_result == "PASS"
            })
        elif v1_result == "PASS" and v2_result == "FAIL":
            regressions.append({
                "example": label,
                "metric": metric,
                "v1_result": "PASS",
                "v2_result": "FAIL"
            })

# --- Compute summary statistics ---
n_fixed = sum(1 for fm in failure_modes if fm["fixed"])
n_unfixed = sum(1 for fm in failure_modes if not fm["fixed"])
n_regressions = len(regressions)
total_checks = len(src_v1) * len(metric_cols)
v2_pass_count = sum(
    1 for _, row in src_v2.iterrows()
    for m in metric_cols if row[m] == "PASS"
)

# --- Acceptance recommendation ---
if n_regressions > 0:
    recommendation = "CONDITIONAL"
    rationale = (
        f"V2 fixes {n_fixed} failure mode(s) but introduces {n_regressions} regression(s). "
        f"Review regressions before approving."
    )
elif n_unfixed > 0:
    recommendation = "CONDITIONAL"
    rationale = (
        f"V2 fixes {n_fixed} of {len(failure_modes)} V1 failure modes with no regressions, "
        f"but {n_unfixed} failure mode(s) remain. Evaluate whether remaining failures are acceptable."
    )
elif n_fixed > 0:
    recommendation = "ACCEPT"
    rationale = (
        f"V2 fixes all {n_fixed} V1 failure mode(s) with no regressions. "
        f"{v2_pass_count}/{total_checks} metric-example checks pass."
    )
else:
    recommendation = "ACCEPT"
    rationale = "No failure modes detected in V1 or V2. All checks pass."

# --- Assemble the TSR ---
tsr = {
    "test_summary_report": {
        "title": "Golden Dataset Acceptance: V1 vs V2 System Prompt",
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "data_source": source_label,
        "pull_request": {
            "branch": git_branch,
            "commit_sha": git_sha,
            "short_sha": git_short_sha,
            "description": (
                "Refine system prompt to add explicit prohibitions on rate quotes, "
                "outcome guarantees, and pressure tactics. Add required disclaimer."
            )
        },
        "prompts": {
            "system_prompt": {
                "baseline": {"version": "v1", "text": SYSTEM_PROMPT_V1},
                "candidate": {"version": "v2", "text": SYSTEM_PROMPT_V2}
            },
            "judge_evaluation_steps": {
                "baseline": {
                    "version": "v1",
                    "metric": regulatory_compliance.name,
                    "steps": regulatory_compliance.evaluation_steps
                },
                "candidate": {
                    "version": "v2",
                    "metric": regulatory_compliance_v2.name,
                    "steps": regulatory_compliance_v2.evaluation_steps
                }
            }
        },
        "dataset": {
            "name": "mortgage_golden_dataset",
            "total_examples": len(src_v1),
            "metrics_evaluated": metric_cols
        },
        "failure_modes_identified": failure_modes,
        "regressions_introduced": regressions,
        "summary": {
            "total_metric_checks": total_checks,
            "v1_failures": len(failure_modes),
            "v2_fixes": n_fixed,
            "v2_remaining_failures": n_unfixed,
            "v2_regressions": n_regressions,
            "v2_pass_rate": round(v2_pass_count / total_checks, 3) if total_checks > 0 else None
        },
        "acceptance": {
            "recommendation": recommendation,
            "rationale": rationale
        }
    }
}

print(_json.dumps(tsr, indent=2))

